R(8631,"Los leotardos Enigma",[[description="¿Deseas demostrar cuánto vales a los de mi especie, mortal? Vale, quizás podemos ayudarnos mutuamente.$B$BEl antiguo gusano de arena, Ouro, es un ser cuyo poder es legendario. Se rumorea que el propio dios antiguo lo creó como una burla a la vida.$B$BSu piel no es natural... gruesa, casi impenetrable aunque flexible, lo que le permite desplazarse velozmente y con la gracia de criaturas mucho más pequeñas.$B$BTráeme una muestra de su piel y otros componentes menores y te fabricaré unas poderosas mallas.",objectives={"Llévale la piel intacta de Ouro, 2 ídolos del sabio, 5 escarabajos de plata y 5 escarabajos de hueso a Kandrostrasz en Ahn'Qiraj. También debes alcanzar la reputación de amistoso ante el Linaje de Nozdormu para completar esta misión."}]])
R(8632,"El aro Enigma",[[description="Los Emperadores Gemelos... sus incesantes susurros se cobran lentamente un precio sobre mi sano juicio. Se mofan de mí, a sabiendas de que no puedo dar un paso más en sus dominios para salvar a mi hermano Arygos.$B$BTengo visiones de sus monstruosos rostros y su poderosa corona. Pero me vengaré... Transformaré esos símbolos de poder qiraji en unos más adecuados a nuestras necesidades.$B$BTráeme los componentes que necesito, $n. Te daré una celada de poder único.",objectives={"Llévale el aro de Vek'lor, 2 ídolos de la noche, 5 escarabajos de bronce y 5 escarabajos de marfil a Andorgos en Ahn'Qiraj. También debes alcanzar la reputación de amistoso ante el Linaje de Nozdormu para completar esta misión."}]])
R(8633,"Togas Enigma",[[description="El inmencionable dios antiguo se despierta despacio de su sueño bajo Ahn'Qiraj. El terrible sino que aguarda a Azeroth podría llegar dentro de unos días o unos años; el tiempo nada significa para seres con su poder.$B$BCuando los astros sean favorables, desatará su ira contra todo ser viviente. Debes hallarlo antes de que ocurra y encontrar la forma de poner fin a su existencia.$B$BHazlo y tráeme un pedazo de sus restos. Te concederé una armadura como ningún mortal ha llevado... ¡una armadura hecha para quien ha acabado con un Dios!",objectives={"Llévale la coraza del dios antiguo, 2 ídolos del sol, 5 escarabajos de oro y 5 escarabajos de terracota a Vethsera en Ahn'Qiraj. También debes alcanzar la reputación de Honorable ante el Linaje de Nozdormu para completar esta misión."}]])
R(8634,"Las botas Enigma",[[description="La magia qiraji es poderosa y antigua. Los más poderosos qiraji empuñan objetos de tal potencia que harían vacilar hasta a un dragón.$B$BTráeme las ataduras de dominancia qiraji y otros componentes menores y crearé un par de poderosas botas para ti.$B$BTe servirán cuando te enfrentes al enemigo.",objectives={"Llévale las ataduras de dominancia qiraji, 2 ídolos del sol, 5 escarabajos de plata y 5 escarabajos de cristal a Kandrostrasz en Ahn'Qiraj. Esta misión requiere la reputación neutral con la facción Linaje de Nozdormu."}]])
R(8635,"Parterroca el Ancestro")
R(8636,"Rocaestruendo el Ancestro")
R(8637,"Las botas de mortífero",[[description="La magia qiraji es poderosa y antigua. Los más poderosos qiraji empuñan objetos de tal potencia que harían vacilar hasta a un dragón.$B$BTráeme las esclavas de mando qiraji y otros componentes menores y crearé un par de poderosas botas para ti.$B$BTe servirán cuando te enfrentes al enemigo.",objectives={"Llévale las ataduras de mando qiraji, 2 ídolos de la disputa, 5 escarabajos de cristal y 5 escarabajos de hueso a Kandrostrasz en Ahn'Qiraj. Esta misión requiere la reputación neutral con la facción Linaje de Nozdormu."}]])
R(8638,"El jubón de mortífero",[[description="El inmencionable dios antiguo se despierta despacio de su sueño bajo Ahn'Qiraj. El terrible sino que aguarda a Azeroth podría llegar dentro de unos días o unos años; el tiempo nada significa para seres con su poder.$B$BCuando los astros sean favorables, desatará su ira contra todo ser viviente. Debes hallarlo antes de que ocurra y encontrar la forma de poner fin a su existencia.$B$BHazlo y tráeme un pedazo de sus restos. Te concederé una armadura como ningún mortal ha llevado... ¡una armadura hecha para quien ha acabado con un Dios!",objectives={"Llévale el caparazón del dios antiguo, 2 ídolos de la disputa, 5 escarabajos de bronce y 5 escarabajos de marfil a Vethsera en Ahn'Qiraj. También debes alcanzar la reputación de honorable ante el Linaje de Nozdormu para completar esta misión."}]])
R(8639,"El casco de mortífero",[[description="Los Emperadores Gemelos... sus incesantes susurros se cobran lentamente un precio sobre mi sano juicio. Se mofan de mí, a sabiendas de que no puedo dar un paso más en sus dominios para salvar a mi hermano Arygos.$B$BTengo visiones de sus monstruosos rostros y su poderosa corona. Pero me vengaré... Transformaré esos símbolos de poder qiraji en unos más adecuados a nuestras necesidades.$B$BTráeme los componentes que necesito, $n. Te daré una celada de poder único.",objectives={"Llévale la diadema de Vek'lor, 2 ídolos de la guerra, 5 escarabajos de oro y 5 escarabajos de terracota a Andorgos en Ahn'Qiraj. También debes alcanzar la reputación de amistoso ante el Linaje de Nozdormu para completar esta misión."}]])
R(8640,"Los leotardos de mortífero",[[description="¿Deseas demostrar cuánto vales a los de mi especie, mortal? Vale, quizás podemos ayudarnos mutuamente.$B$BEl antiguo gusano de arena, Ouro, es un ser cuyo poder es legendario. Se rumorea que el propio dios antiguo lo creó como una burla a la vida.$B$BSu piel no es natural... gruesa, casi impenetrable aunque flexible, lo que le permite desplazarse velozmente y con la gracia de criaturas mucho más pequeñas.$B$BTráeme una muestra de su piel y otros componentes menores y te fabricaré unas poderosas mallas.",objectives={"Llévale la piel intacta de Ouro, 2 ídolos de la noche, 5 escarabajos de hueso y 5 escarabajos de cristal a Kandrostrasz en Ahn'Qiraj. También debes alcanzar la reputación de amistoso ante el Linaje de Nozdormu para completar esta misión."}]])
R(8641,"Las hombreras de mortífero",[[description="Se cuenta entre nosotros que el adorno de la armadura de los hombros que llevan las razas mortales se inspiró en un intento de emular las alas de un dragón.$B$BTráeme las esclavas que llevan los más importantes líderes qiraji y con ellas te forjaré unas hombreras ¡más temidas que las alas del mismísimo Nefarian!",objectives={"Llévale las ataduras de mando qiraji, 2 ídolos del sol, 5 escarabajos de plata y 5 escarabajos de terracota a Andorgos en Ahn'Qiraj. También debes alcanzar la reputación neutral ante el Linaje de Nozdormu para completar esta misión."}]])
