R(8693,"La capa de las sombras ocultas",[[description="Vaya, ¡cómo me alegra oír que nos ayudarás en el ataque a Ahn'Qiraj, $n! Puedo prepararte una protección que te ayudará en el combate contra el enemigo, $c.$B$BNecesitaré un manto qiraji, al que le daré tus medidas, claro. También necesitaré ídolos y escarabajos para confeccionarte un pasador apropiado.$B$BTe lo prometo, no te decepcionaré.",objectives={"Llévale 1 mantón marcial qiraji, 2 ídolos azures, 5 escarabajos de bronce y 5 escarabajos de marfil a Keyl Patacerce en Silithus. También debes alcanzar la reputación de venerado ante el Círculo Cenarion para completar esta misión."}]])
R(8694,"El sayo de los nombres prohibidos",[[description="Vaya, ¡cómo me alegra oír que nos ayudarás en el ataque a Ahn'Qiraj, $n! Puedo prepararte una protección que te ayudará en el combate contra el enemigo, $c.$B$BNecesitaré un manto qiraji, al que le daré tus medidas, claro. También necesitaré ídolos y escarabajos para confeccionarte un pasador apropiado.$B$BTe lo prometo, no te decepcionaré.",objectives={"Llévale 1 mantón qiraji regio, 2 ídolos de ámbar, 5 escarabajos de marfil y 5 escarabajos de bronce a Keyl Patacerce en Silithus. También debes alcanzar la reputación de venerado ante el Círculo Cenarion para completar esta misión."}]])
R(8695,"El manteo de justicia eterna",[[description="Vaya, ¡cómo me alegra oír que nos ayudarás en el ataque a Ahn'Qiraj, $n! Puedo prepararte una protección que te ayudará en el combate contra el enemigo, $c.$B$BNecesitaré un manto qiraji, al que le daré tus medidas, claro. También necesitaré ídolos y escarabajos para confeccionarte un pasador apropiado.$B$BTe lo prometo, no te decepcionaré.",objectives={"Llévale 1 mantón qiraji regio, 2 ídolos de obsidiana, 5 escarabajos de oro y 5 escarabajos de terracota a Keyl Patacerce en Silithus. También debes alcanzar la reputación de venerado ante el Círculo Cenarion para completar esta misión."}]])
R(8696,"La capa de la senda oculta",[[description="Vaya, ¡cómo me alegra oír que nos ayudarás en el ataque a Ahn'Qiraj, $n! Puedo prepararte una protección que te ayudará en el combate contra el enemigo, $c.$B$BNecesitaré un manto qiraji, al que le daré tus medidas, claro. También necesitaré ídolos y escarabajos para confeccionarte un pasador apropiado.$B$BTe lo prometo, no te decepcionaré.",objectives={"Llévale 1 mantón qiraji regio, 2 ídolos luminiscentes, 5 escarabajos de piedra y 5 escarabajos de cristal a Keyl Patacerce en Silithus. También debes alcanzar la reputación de venerado ante el Círculo Cenarion para completar esta misión."}]])
R(8697,"El anillo de infinitia sabiduría",[[description="Se rumorea que los anillos que los tenientes qiraji llevan les confieren formidables poderes. Las corruptas gemas engarzadas en estos anillos podrían, en teoría, cambiarse por materiales puros para crear versiones sin corrupción de los anillos.$B$BLas gemas engastadas en los ídolos qiraji deberían servir, ya que son de la más elevada calidad.$B$BTráeme el anillo y los ídolos, y te haré un poderoso anillo, $c.",objectives={"Llévale 1 anillo ceremonial qiraji, 2 ídolos de obsidiana, 5 escarabajos de plata y 5 escarabajos de hueso a Clamavientos Yessendra en Silithus. También debes alcanzar la reputación de honorable ante el Círculo Cenarion para completar esta misión."}]])
R(8698,"El anillo de la inminente tormenta",[[description="Se rumorea que los anillos que los tenientes qiraji llevan les confieren formidables poderes. Las corruptas gemas engarzadas en estos anillos podrían, en teoría, cambiarse por materiales puros para crear versiones sin corrupción de los anillos.$B$BLas gemas engastadas en los ídolos qiraji deberían servir, ya que son de la más elevada calidad.$B$BTráeme el anillo y los ídolos, y te haré un poderoso anillo, $c.",objectives={"Llévale 1 anillo qiraji magistral, 2 ídolos bermellones, 5 escarabajos de plata y 5 escarabajos de hueso a Clamavientos Yessendra en Silithus. También debes alcanzar la reputación de honorable ante el Círculo Cenarion para completar esta misión."}]])
