R(8728,"Buenas y malas noticias",[[description="Vaya, ha llevado más tiempo del que esperaba. Ahora deja que vea qué dice este libro de contabilidad.$B$B<Narain lee el libro en silencio y murmura de vez en cuando.>$B$BLa buena noticia es que estoy seguro al 99% de que podré crear una boya de arcanita que funcionará como tú quieres. Eso, claro está, depende de la mala noticia...$B$BLa mala noticia es que voy a necesitar mucha arcanita, elementium y unas gemas raras.$B$BTráeme lo que necesito y te haré la boya.",objectives={"Narain Sabelotodo de Tanaris quiere que le lleves 20 barras de arcanita, 10 menas de elementium, 10 diamantes de Azeroth y 10 zafiros azules."}]])
R(8729,"La cólera de Neptulon",[[description="¿Te he dado ya la mala noticia? Se llama Fauces: 30 metros de muerte y destrucción. Supongo que me he olvidado esa menudencia.$B$BMi superior clarividencia psico-psiónica me indica que el mejor lugar para lanzar esta boya está en la costa de Azshara: la Bahía de la Tempestad.$B$BBusca un remolino lleno de restos de naufragios.$B$BPor cierto, espero que tengas amigos.$B$BY, si por algún milagro, tienes éxito, lleva el fragmento de cetro a Anacronos.",objectives={"Utiliza la boya de arcanita en La Vorágine espiral de la Bahía de la Tempestad de Azshara."}]])
R(8730,"La corrupción de Nefarius",[[description="¿Eres tú, Campeón? Mil años hace que me fue confiado este fragmento, y en triste hora vienen a arrebatármelo... Pero ¿qué sería una tragedia sin crueldad?$B$B<Vaelastrasz tose débilmente.>$B$BEl... El fragmento de cetro está en poder de Nefarius.$B$BEl tiempo corre en nuestra contra. Nefarius planea destruirlo. ¡Apresúrate!",objectives={"Mata a Nefarian y recupera del fragmento de cetro rojo. Llévaselo a Anacronos a las Cavernas del Tiempo, en Tanaris. Tienes una hora y media para completar esta tarea."}]])
R(8731,"Servicio de campo",[[description="Hola, $n. Antes de poder asignarte tareas más complicadas en la guerra, tendrás que hacer tu parte en el campo de batalla.$B$BEncontrarás al capitán Machacacráneos de la Legión de Orgrimmar fuera de Colmen'Regal.$B$BPreséntate ante él y vuelve a verme con alguna prueba de tu servicio. Tendré una misión más avanzada lista para ti.$B$BOh y, por favor, no te acerques a la Brigada de Forjaz. Hay mucha tensión entre nuestros voluntarios de la Alianza y la Horda.",objectives={"Preséntate ante Krug Machacacráneos en la Avanzada de la Legión de Orgrimmar delante de Colmen'Regal. Prepara tu documentación de instrucción de campo sin firmar, consigue la documentación de instrucción de campo firmada y llévaselas a Clamavientos Kaldon en el Fuerte Cenarion.$B$BNota: curar o lanzar hechizos benéficos a un miembro de la Legión de Orgrimmar, te marcará como JcJ."}]])
R(8732,"Documentación de instrucción de campo")
R(8733,"Eranikus, el Tirano del Sueño",[[description="Este es un viaje de redención, $ghéroe:heroína;. Si la muerte viniera a buscarme hoy, habría muerto por una causa justa. Debes recuperar el fragmento de cetro verde. Debes librar a Eranikus de la mácula con la que los dioses antiguos le han mancillado.$B$BViaja a Darnassus. Fuera de la ciudad encontrarás a uno de mis agentes. Este agente pondrá el mecanismo en marcha e informará a Tyrande de nuestros planes sin alertar a Corzocelada.$B$B<Malfurion suspira.>$B$BUna caída en desgracia que lleva fraguándose mil años...",objectives={"Viaja al continente de Teldrassil y busca al agente de Malfurion. Lo encontrarás a lo largo de los muros de Darnassus.|n"}]])
R(8734,"Tyrande y Rémulos",[[description="Tyrande sabrá de esto, mortal. Shan'do Tempestira me ha preparado para esta contingencia.$B$BAhora debes ir a Claro de la Luna a hablar con Remulos. Él tendrá más instrucciones para invocar a Eranikus.$B$BBuena suerte.",objectives={"Ve a Claro de la Luna y habla con el guardián Remulos."}]])
R(8735,"Corrupción de Pesadilla",[[description="Debes ir a los cuatro portales del Sueño de Azeroth. Debes conseguir un fragmento de Corrupción de Pesadilla en cada uno de ellos. Están en poder de los dragonantes que viven allí. Regresa cuando hayas conseguido los fragmentos.",objectives={"Ve a los 4 Portales del Sueño Esmeralda de Azeroth y recoge un fragmento de Corrupción de Pesadilla en cada uno. Habla otra vez con el guardián Remulos en Claro de la Luna cuando hayas completado la tarea.|n"}]])
R(8736,"La Pesadilla se manifiesta",[[description="Debemos restringir el uso de la fuerza contra Eranikus. Queremos redimirlo, no aniquilarlo.$b$bTyrande está de camino para ayudarnos. Hemos de resistir las embestidas del dragón y salvar Amparo de la Noche.$b$b¡No bajes la guardia! Tú y tus aliados sois nuestra única esperanza.|n",objectives={"Defiende Amparo de la Noche de Eranikus. No dejes morir al guardián Remulos. No mates a Eranikus. Defiéndete. Espera a Tyrande.|n"}]])
R(8737,"Templario azur",[[description="El Martillo Crepuscular y los nobles elementales a quienes adoran, suponen una amenaza formidable para nuestras operaciones en Silithus. Con los nuevos enemigos a los que nos enfrentamos dentro de Ahn'Qiraj, no podemos permitirnos bajar la guardia con nuestros enemigos del exterior.$B$BEncuentra la forma de invocar y destruir a un Templario azur y vete a informar a Bor Ferocrín.",objectives={"Invoca y mata a un Templario azur y preséntate ante Bor Ferocrín en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas I para poder completar la misión."}]])
R(8738,"Informe de exploración de Colmen'Regal",[[description="Hemos enviado a nuestros mejores exploradores a las colmenas de silítidos para reunir información. El explorador Landion lleva varios días observando los movimientos de los silítidos en Colmen'Regal. Encuéntrale y consigue un informe por escrito. Necesitamos esa información lo antes posible para saber cómo actuar, $n.",objectives={"Contacta con el explorador Cenarion Landion en Colmen'Regal y entrega el informe de exploración de Colmen'Regal a Clamavientos Cuerno Digno en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas VII para poder completar la misión."}]])
R(8739,"Informe de exploración de Colmen'Ashi",[[description="Hemos enviado a nuestros mejores exploradores a las colmenas de silítidos para reunir información. La exploradora Jalia lleva varios días observando los movimientos de los silítidos en Colmen'Ashi. Encuéntrala y consigue un informe por escrito. Necesitamos esa información lo antes posible para saber cómo actuar, $n.",objectives={"Contacta con el explorador Cenarion Jalia en Colmen'Ashi y entrega el informe de exploración de Colmen'Ashi a Clamavientos Cuerno Digno en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas VIII para poder completar la misión."}]])
R(8740,"Los merodeadores Crepusculares",[[description="Hemos avistado bandas de adeptos montados del Martillo Crepuscular asaltando a nuestras patrullas y caravanas más pequeñas, pero quedan fuera del alcance de nuestras tropas en el Fuerte Cenarion.$B$BEncuentra y derrota a los forajidos y a su líder, un terrible guerrero llamado Morna. Vete a informar a Clamavientos Cuerno Digno cuando completes la misión.",objectives={"Mata a la maleante Crepuscular Morna y a 2 maleantes Crepusculares. Informa a Clamavientos Cuerno Digno cuando hayas completado tu misión. También debes llevar el Informe de tareas tácticas IX para poder completar la misión."}]])
R(8741,"El regreso del Campeón",[[description="El guardián te espera, $n. Lleva el fragmento de cetro verde a Anacronos, que está en las Cavernas del Tiempo.|n",objectives={"Lleva el fragmento de cetro verde a Anacronos a las Cavernas del Tiempo, en Tanaris.|n"}]])
