R(8770,"Objetivo: los defensores de Colmen'Ashi",[[description="Según progresa la guerra, la presencia de silítidos en la zona supone una amenaza constante para nuestras operaciones. Te han seleccionado para participar en un asalto a Colmen'Ashi donde tu objetivo principal consistirá en los defensores Colmen'Ashi.$B$BInforma a la comandante Mar'alith cuando hayas terminado tu misión.",objectives={"Mata 30 defensores Colmen'Ashi y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate I para poder completar la misión."}]])
R(8771,"Objetivo: los acecharenas de Colmen'Ashi",[[description="Según progresa la guerra, la presencia de silítidos en la zona supone una amenaza constante para nuestras operaciones. Te han seleccionado para participar en un asalto a Colmen'Ashi donde tu objetivo principal consistirá en los acecharenas Colmen'Ashi.$B$BInforma al comandante Mar'alith cuando hayas terminado u misión.",objectives={"Mata 30 acecharenas Colmen'Ashi y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate II para poder completar la misión."}]])
R(8772,"Objetivo: los oteadores de Colmen'Zora",[[description="Se han pedido refuerzos para unirse al asalto a Colmen'Zora. Te han seleccionado para atacar a los oteadores de Colmen'Zora. Informa a la comandante Mar’alith cuando hayas completado tu misión.",objectives={"Mata 30 oteadores de Colmen'Zora y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate VI para poder completar la misión.|n"}]])
R(8773,"Objetivo: los atracadores de Colmen'Zora",[[description="Se han pedido refuerzos para unirse al asalto a Colmen'Zora. Te han seleccionado para atacar a los atracadores de Colmen'Zora. Informa a la comandante Mar’alith cuando hayas completado tu misión.",objectives={"Mata 30 atracadores de Colmen'Zora y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate IV para poder completar la misión."}]])
R(8774,"Objetivo: los emboscadores de Colmen'Regal",[[description="Según progresa la guerra, la presencia de silítidos en la zona supone una amenaza constante para nuestras operaciones. Te han seleccionado para participar en un asalto a Colmen'Regal donde tu objetivo principal consistirá en los emboscadores Colmen'Regal.$B$BInforma al comandante Mar'alith cuando hayas terminado tu misión.",objectives={"Mata 30 emboscadores Colmen'Regal y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate VIII para poder completar la misión.|n"}]])
R(8775,"Objetivo: los escupefuego de Colmen'Regal",[[description="Según progresa la guerra, la presencia de silítidos en la zona supone una amenaza constante para nuestras operaciones. Te han seleccionado para participar en un asalto a Colmen'Regal donde tu objetivo principal consistirá en los escupefuegos aéreos Colmen'Regal.$B$BInforma al comandante Mar'alith cuando hayas terminado tu misión.",objectives={"Mata 30 escupefuegos Colmen'Regal y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate IX para poder completar la misión.|n"}]])
R(8776,"Objetivo: los esclavizadores de Colmen'Regal",[[description="Según progresa la guerra, la presencia de silítidos en la zona supone una amenaza constante para nuestras operaciones. Te han seleccionado para participar en un asalto a Colmen'Regal donde tu objetivo principal consistirá en los esclavizadores Colmen'Regal.$B$BInforma al comandante Mar'alith cuando hayas terminado tu misión.",objectives={"Mata 30 esclavizadores Colmen'Regal y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate X para poder completar la misión.|n"}]])
R(8777,"Objetivo: los hurgadores de Colmen'Regal",[[description="Según progresa la guerra, la presencia de silítidos en la zona supone una amenaza constante para nuestras operaciones. Te han seleccionado para participar en un asalto a Colmen'Regal donde tu objetivo principal consistirá en los perforadores Colmen'Regal.$B$BInforma al comandante Mar'alith cuando hayas terminado tu misión.",objectives={"Mata 30 perforadores Colmen'Regal y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate XI para poder completar la misión.|n"}]])
R(8778,"La Brigada de Forjaz necesita explosivos",[[description="La Brigada de Forjaz ha solicitado un extraño pedido de componentes... muy volátiles. Reúnelos y llévaselos al señor Bocafuente de la Brigada de Forjaz.",objectives={"Lleva 6 aceites de inmolación, 5 combustibles de cohete goblin y 10 unidades de pólvora densa al arcanista Bocafuente cerca de Colmen'Zora en Silithus. También debes llevar el Informe de tareas logísticas IV para poder completar la misión."}]])
R(8779,"Materiales de visión",[[description="Los estudios de la Geóloga Trotuina han demostrado ser de gran valor para nuestras operaciones en Silithus. Recientemente, ha solicitado materiales de visión para utilizar en su investigación.$B$BPor favor, consigue esos materiales y llévaselos directamente a ella para que pueda continuar con su investigación.",objectives={"Lleva 1 fragmento luminoso grande, 1 fragmento radiante grande y 1 esmeralda enorme a la Geóloga Trotuina en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas V para poder completar la misión."}]])
R(8780,"Refuerzos para armadura para el campo de batalla",[[description="El suministro de refuerzos para armadura de la Brigada de Forjaz en el campo de batalla, está empezando a escasear peligrosamente. Consigue un lote de refuerzos y llévaselo a Janela Martillotenaz en la Avanzada de la Brigada de Forjaz, justo fuera de Colmen'Zora.",objectives={"Lleva 8 refuerzos para armadura bastos y 8 refuerzos para armadura pesados a Janela Martillotenaz en la Avanzada de la Brigada de Forjaz, cerca de Colmen'Zora, en Silithus. También debes llevar el Informe de tareas logísticas VII para poder completar la misión."}]])
R(8781,"Armas para el campo de batalla",[[description="La Brigada de Forjaz ha sido un poderoso aliado en nuestra batalla en Silithus. Por desgracia, perdieron muchos suministros de camino hacia aquí. Consigue un lote de armas y llévaselo a Janela Martillotenaz, está cerca de Colmen'Zora.",objectives={"Lleva 2 espadas anchas de acero lunar a Janela Martillotenaz en la Avanzada de la Brigada de Forjaz, en las afueras de Colmen'Zora. También debes llevar el Informe de tareas logísticas VI para poder completar la misión."}]])
R(8782,"Suministros para uniformes",[[description="La última entrada de voluntarios ha provocado escasez de uniformes. Consigue un lote de materiales de uniforme y llévaselo a Clamavientos Cuerno Digno.",objectives={"Lleva 1 tela lunar, 2 madejas de paño rúnico y 1 seda de araña Tejehierro a Clamavientos Cuerno Digno en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas VIII para poder completar la misión."}]])
R(8783,"Materiales encantados",[[description="Vargus, el herrero del Fuerte Cenarion, ha solicitado materiales encantados para crear poderosas armas para nuestras tropas. Consíguelos y llévaselos directamente a Vargus para que las tropas del Fuerte Cenarion puedan seguir estando bien equipadas.",objectives={"Lleva 2 barras de torio encantado y 2 cueros encantados a Vargus en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas IX para poder completar la misión."}]])
R(8784,"Los secretos de los qiraji",[[description="¡Has descubierto un antiguo artefacto de Ahn'Qiraj! Esta reliquia quizás sea de utilidad para uno de los dragones que se encuentra cerca de la puerta del templo.",objectives={"Llévale el artefacto antiguo qiraji a los dragones ocultos cerca de la entrada del templo.|n"}]])
R(8785,"¡La Legión de Orgrimmar necesita mojo!",[[description="La Legión de Orgrimmar ha solicitado varios ingredientes muy poco usuales. Dada su situación actual en Silithus, queremos entregarles los suministros tan pronto como podamos. Reúne los materiales y llévaselos a la trol llamada Shai.",objectives={"Lleva 6 mojos potentes, 6 frascos de gran mojo y 8 aceites de inmolación a la sacerdotisa de las Sombras Shai cerca de Colmen'Regal, en Silithus. También debes llevar el Informe de tareas logísticas IV para poder completar la misión."}]])
R(8786,"Armas para el campo de batalla",[[description="La Legión de Orgrimmar ha solicitado unas armas adicionales que no hemos sido capaces de suministrar. Consigue las armas que nos han pedido y llévaselas a Merok Zancada Larga fuera de Colmen'Regal.",objectives={"Lleva 3 hachas de hierro macizo a Merok Zancada Larga en el campamento de la Legión de Orgrimmar, en las afueras de Colmen'Regal. También debes llevar el Informe de tareas logísticas VI para poder completar la misión."}]])
R(8787,"Complementos para armadura para el campo de batalla",[[description="Los valientes voluntarios de la Legión de Orgrimmar han venido a Silithus para ayudarnos en nuestra causa. De alguna forma, perdieron sus refuerzos para armadura durante el viaje. Consigue un lote de armaduras y llévaselas a Merok Zancada Larga al campamento de la Legión de Orgrimmar.",objectives={"Lleva 8 refuerzos para armadura bastos y 8 refuerzos para armadura pesados a Merok Zancada Larga, cerca de Colmen'Regal. También debes llevar el Informe de tareas logísticas VII para poder completar la misión."}]])
R(8788,"Un obsequio ligeramente agitado")
R(8789,"Armamentos imperiales qiraji",[[description="No hemos estado ociosos durante un milenio, $n.$B$BHemos estado observando cómo estas bestias lo celebraban a solas cuando habían cumplido su propósito. Hemos estado escuchando cómo tramaban y se confabulaban para destruir nuestro mundo. Y nos hemos enterado de sus propias traiciones internas.$B$BExisten puntos débiles y sabemos cómo usarlos a nuestro favor.$B$BEncuentra sus armamentos ceremoniales y tráemelos. Combinados con el elemento creado a partir de la volatilidad de su propio Dios, se convertirán en una fuerza considerable.",objectives={"Arygos en el Templo de Ahn'Qiraj creará armamento imbuido de elementium para ti si le llevas armamento imperial qiraji y 3 lingotes de elementium."}]])
R(8790,"Regalos imperiales Qiraji",[[description="Según una teoría de Arygos el elemento nacido de conflictos entre los dioses antiguos y sus esbirros también es extremadamente fatal para ellos si se dan las condiciones adecuadas. Me refiero al elementium, mortal.$B$BEncuentra un atavío imperial qiraji y tráemelo junto con el elemento tóxico para infundir con ellos armas de gran poder.|n",objectives={"Merithra del Sueño en el Templo de Ahn'Qiraj creará armamento imbuido de elementium para ti si le llevas un atavío imperial qiraji y 3 lingotes de elementium.|n"}]])
R(8791,"La caída de Osirio",[[description="Se acabó esa terrible amenaza. El cruel Osirio ha sido derrotado.$B$BLos vecinos de Kalimdor sentirán gran alivio cuando conozcan la noticia. Coge la cabeza de Osirio y llévasela al comandante Mar'alith de Fuerte Cenarion.",objectives={"Entrégale la cabeza de Osirio el Sinmarcas al comandante Mar'alith de Fuerte Cenarion en Silithus.|n"}]])
R(8792,"¡La Horda te necesita!",[[description="Hola, ¡qué bien que hayas decidido escucharme! La Horda necesita toda la ayuda posible para preparar la guerra de Ahn'Qiraj ¡y eso significa que te necesitamos a ti también! En este mismo instante, los recolectores oficiales están reuniendo el material necesario para la guerra que se avecina, pero no lograremos nuestro objetivo sin tu ayuda, $N!$B$BDeberías hablar con quien está al mando, el señor de la guerra Gorchuk. ¿Qué me dices, $c? ¿Nos ayudarás?",objectives={"Habla con el señor de la guerra Gorchuk en el Valle de los Espíritus de Orgrimmar."}]])
R(8793,"¡La Horda te necesita!",[[description="Hola, ¡qué bien que hayas decidido escucharme! La Horda necesita toda la ayuda posible para preparar la guerra de Ahn'Qiraj ¡y eso significa que te necesitamos a ti también! En este mismo instante, los recolectores oficiales están reuniendo el material necesario para la guerra que se avecina, pero no lograremos nuestro objetivo sin tu ayuda, $n!$B$BDeberías hablar con quien está al mando, el señor de la guerra Gorchuk. ¿Qué me dices, $c? ¿Nos ayudarás con estos preparativos vitales?",objectives={"Habla con el señor de la guerra Gorchuk en el Valle de los Espíritus de Orgrimmar."}]])
R(8794,"¡La Horda te necesita!",[[description="Hola, ¡qué bien que hayas decidido escucharme! La Horda necesita toda la ayuda posible para preparar la guerra de Ahn'Qiraj ¡y eso significa que te necesitamos a ti también! En este mismo instante, los recolectores oficiales están reuniendo el material necesario para la guerra que se avecina, pero no lograremos nuestro objetivo sin tu ayuda, $n!$B$BDeberías hablar con quien está al mando, el señor de la guerra Gorchuk. ¿Qué me dices, $c? ¿Nos ayudarás con estos preparativos vitales?",objectives={"Habla con el señor de la guerra Gorchuk en el Valle de los Espíritus de Orgrimmar."}]])
R(8795,"¡La Alianza te necesita!",[[description="Hola, ¡qué bien que hayas decidido escucharme! La Alianza necesita toda la ayuda posible para preparar la guerra de Ahn'Qiraj ¡y eso significa que te necesitamos a ti también! En este mismo instante, los recolectores oficiales están reuniendo el material necesario para la guerra que se avecina, pero no lograremos nuestro objetivo sin tu ayuda, $N!$B$BDeberías hablar con quien está al mando, el alguacil de campo Avalancha ¿Qué me dices, $c? ¿Nos ayudarás con estos preparativos vitales?",objectives={"Habla con el alguacil de campo Nevanur en La Sala Militar de Forjaz."}]])
R(8796,"¡La Alianza te necesita!",[[description="Hola, ¡qué bien que hayas decidido escucharme! La Alianza necesita toda la ayuda posible para preparar la guerra de Ahn'Qiraj ¡y eso significa que te necesitamos a ti también! En este mismo instante, los recolectores oficiales están reuniendo el material necesario para la guerra que se avecina, pero no lograremos nuestro objetivo sin tu ayuda, $N!$B$BDeberías hablar con quien está al mando, el alguacil de campo Avalancha. ¿Qué me dices, $c? ¿Nos ayudarás con estos preparativos vitales?",objectives={"Habla con el alguacil de campo Nevanur en La Sala Militar de Forjaz."}]])
R(8797,"¡La Alianza te necesita!",[[description="Hola, ¡qué bien que hayas decidido escucharme! La Alianza necesita toda la ayuda posible para preparar la guerra de Ahn'Qiraj ¡y eso significa que te necesitamos a ti también! En este mismo instante, los recolectores oficiales están reuniendo el material necesario para la guerra que se avecina, pero no lograremos nuestro objetivo sin tu ayuda, $N!$B$BDeberías hablar con quien está al mando, el alguacil de campo Avalancha. ¿Qué me dices, $c? ¿Nos ayudarás con estos preparativos vitales?",objectives={"Habla con el alguacil de campo Nevanur en La Sala Militar de Forjaz."}]])
R(8798,"Un yeti propio")
R(8799,"El héroe del día",[[description="Oye, se supone que no tendría que decirte esto, pero como todo el mundo te admira y tal...$b$bEn esta época del año hay mucho acebo, pero no dura nada. Tenemos una máquina que lo conserva siempre fresco. Lo usamos para dar color durante las fiestas... ¡y para hacer negocio en verano!$b$bTe dejo usar el conservador si demuestras tu habilidad en la cocina. Necesitas sal de roca y unos cinco oros. Te prepararé una hornada toda para ti.",objectives={"Lleva 1 porción de sal de roca y 5 monedas de oro al conservante de acebo; recibirás 5 acebos conservados."}]])
R(8800,"Equipamiento de Cenarion",[[description="Cuando vayas completando las misiones que te asignen en la guerra, vete a hablar con Vargus, el herrero. Muéstrale las insignias que hayas obtenido. Te proporcionará equipamiento afín a tu nivel de entrega a nuestra causa.",objectives={"Habla con Vargus en el Fuerte Cenarion, en Silithus."}]])
R(8801,"El legado de C'Thun",[[description="Los muros de Ahn'Qiraj tiemblan. Una fuerza del mal, más antigua que el mismo mundo, ha sido destruida.$B$BAl mirar los restos de esa colosal abominación, casi se te congela el corazón. Incluso después de $gmuerto:muerta;, puedes sentir la herencia de la maldad de C'Thun a tu alrededor.$B$BHas logrado lo que parecía imposible.$B$BConsigues sacar el ojo de ese monstruo y lo pones a buen recaudo en tu bolsa.$B$BLleva el ojo de C'Thun a los dragones de la cámara siguiente.",objectives={"Llévale el ojo de C'Thun a Caelastrasz en el Templo de Ahn'Qiraj."}]])
R(8802,"La salvación de Kalimdor",[[description="Encamínate a las Cavernas del Tiempo, $Gseñor:señora; $n. Anacronos espera que regreses. Dale el ojo de C'Thun porque querrá, sin duda alguna, añadirlo a su colección magistral.|n",objectives={"Llévale el ojo de C'Thun a Anacronos en las Cavernas del Tiempo."}]])
R(8803,"Un regalo de festividad")
R(8804,"Material de supervivencia en el desierto",[[description="Con la llegada de reclutas frescos al Fuerte Cenarion llega también el problema de su supervivencia en el desierto. Las innumerables criaturas venenosas que viven en él y la deshidratación son serias amenazas para los voluntarios poco experimentados. Reúne los suministros necesarios para un equipo de supervivencia en el desierto y llévaselos a Calandrath al Fuerte Cenarion.",objectives={"Lleva 4 globos de agua, 4 contravenenos potentes y 4 albóndigas del desierto ahumadas a Calandrath en la taberna del Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas I para poder completar la misión."}]])
R(8805,"Botas para la guardia",[[description="La división montada de la guardia del Fuerte Cenarion tiene escasez de botas de mitril ornamentado. Consigue un cargamento y entrégaselo inmediatamente al capitán Vish Kozus en el Fuerte Cenarion.",objectives={"Lleva 3 botas de mitril ornamentado a Vish Kozus, Capitán de la guardia del Fuerte Cenarion en Silithus. También debes llevar el Informe de tareas logísticas II para poder completar la misión."}]])
R(8806,"Piedra de pulir para la guardia",[[description="La guardia del Fuerte Cenarion tiene escasez de muelas. Consigue un cargamento y entrégaselo inmediatamente al capitán Vish Kozus en el Fuerte Cenarion.",objectives={"Lleva 10 piedras de pulir densas, 10 piedras de pulir sólidas y 10 piedras de pulir pesadas a Vish Kozus, Capitán de la guardia del Fuerte Cenarion en Silithus. También debes llevar el Informe de tareas logísticas III para poder completar la misión."}]])
R(8807,"Materiales de visión",[[description="Los estudios de la Geóloga Trotuina han demostrado ser de gran valor para nuestras operaciones en Silithus. Recientemente, ha solicitado materiales de visión para utilizar en su investigación.$B$BPor favor, consigue esos materiales y llévaselos directamente a ella para que pueda continuar con su investigación.",objectives={"Lleva 1 fragmento luminoso grande, 1 fragmento radiante grande y 1 esmeralda enorme a la Geóloga Trotuina en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas V para poder completar la misión."}]])
R(8808,"Suministros para uniformes",[[description="La última entrada de voluntarios ha provocado escasez de uniformes. Consigue un lote de materiales de uniforme y llévaselo a Clamavientos Cuerno Digno.",objectives={"Lleva 1 tela lunar, 2 madejas de paño rúnico y 1 seda de araña Tejehierro a Clamavientos Cuerno Digno en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas VIII para poder completar la misión."}]])
R(8809,"Materiales encantados",[[description="Vargus, el herrero del Fuerte Cenarion, ha solicitado materiales encantados para crear poderosas armas para nuestras tropas. Consíguelos y llévaselos directamente a Vargus para que las tropas del Fuerte Cenarion puedan seguir estando bien equipadas.",objectives={"Lleva 2 barras de torio encantado y 2 cueros encantados a Vargus en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas IX para poder completar la misión."}]])
R(8810,"Vendas para el campo de batalla",[[description="Debido a las víctimas que hemos tenido recientemente, nuestro suministro de vendajes en el campo de batalla empieza a escasear peligrosamente. Consigue un lote de suministros de primeros auxilios y llévaselo a Clamavientos Cuerno Digno en el Fuerte Cenarion.",objectives={"Lleva 30 vendas de paño rúnico gruesas, 30 vendas de seda gruesas y 30 vendas de tejido mágico gruesas a Clamavientos Cuerno Digno en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas X para poder completar la misión."}]])
