R(9063,"Torwa Abrecaminos",[[description="Un cazador llamado Torwa Abrecaminos ha solicitado la ayuda de un druida. Dijo que solo nosotros tenemos las habilidades necesarias y el respeto por la naturaleza para ayudarlo.$b$bExiste un camino que conecta el Cráter de Un'Goro con el desierto de Tanaris. Encontrarás a Torwa justo al terminar el camino, al llegar al Cráter.",objectives={"Habla con Torwa Abrecaminos en el Cráter de Un'Goro."}]])
R(9065,"The \"Chow\" Quest (123)aa",[[description="$Tpunk;!  Kill Kobold Vermin, 2 of em.",objectives={"Kill Kobold Vermin, 2 of em."}]])
R(9068,"La túnica Fatalidad",[[description="¿Puedes hacerme el honor de devolver la armadura de los que cayeron defendiendo estas tierras?$b$bHa sido profanada y sin duda destinada a fines maléficos; pero puede renovarse con restos de armadura y utilizada de nuevo.$b$bTráeme los restos de los caídos e ingredientes de purificación y Rompeterra será toda tuya.$b$bBusca en Naxxramas.",objectives={"Rimblat Rompeterra de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, te hará una guerrera Rompeterra si le llevas lo siguiente: 1 guerrera profanada, 25 restos de malla, 4 barras de arcanita y 3 pellejos bastos curtidos."}]])
