R(9304,"Un documento del frente",[[description="Has encontrado esta carta en uno de los muchos esbirros de la Plaga que has liquidado. Por el aspecto y el olor, el no-muerto la llevó consigo durante bastante tiempo. Puede que a alguien de la Capilla de la Esperanza de la Luz le interese examinarla más atentamente...",objectives={"Lleva el documento manchado al Guardián de los Pergaminos de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este."}]])
R(9310,"Cristal necrótico tenue",[[description="En el cadáver de la criatura encuentras un cristal quebrado que pulsa lentamente con energía necrótica.",objectives={"LLeva el cristal necrótico al general Rukag, que está fuera de las puertas de Entrañas."}]])
R(9317,"Piedras de afilar consagradas")
R(9318,"Aceite de zahorí bendito")
R(9319,"Una luz en la oscuridad",[[description="No somos los únicos en celebrar este día, $n. La llama influye en todas las criaturas, todas las culturas. Se están encendiendo hogueras incluso en los lugares más oscuros.$B$BSi deseas verlas, desciende a las profundidades. Busca las hogueras que arden en Stratholme, en Scholomance, entre los ogros de La Masacre y en los salones de Cumbre de Roca Negra. Esperaré tu regreso.",objectives={"Toca las hogueras de Cumbre de Roca Negra, La Masacre, Scholomance y Stratholme, y ve a ver al guardián de la llama del Festival."}]])
R(9320,"Poción sublime de maná")
R(9321,"Poción sublime de curación")
R(9322,"Los fuegos salvajes de Kalimdor",[[description="El Festival del Solsticio se celebra en todo Azeroth y las ricas tierras de Kalimdor no son una excepción. Parece que te gusta viajar; voy a darte un motivo para hacerlo.$b$bNo apreciarás realmente el solsticio de verano hasta que hayas visto las hogueras azules que arden por todas partes. Se han encendido hogueras en la helada Cuna del Invierno, al nordeste de Azshara, cerca de Sosiego del Valor en los eriales de Silithus y junto a la entrada del exuberante Un'Goro. Regresa cuando hayas completado tu viaje.",objectives={"Visita los campamentos del Solsticio de Azshara, Silithus, Cráter de Un'Goro y Cuna del Invierno y ve a ver al guardián de la llama."}]])
R(9323,"Los fuegos salvajes de los Reinos del Este",[[description="Esta celebración de la llama se extiende por toda la tierra, $c. No hay un solo lugar que no sienta el calor de esta fiesta y las hogueras más brillantes resplandecen en azul. Búscalas.$B$BEncontrarás una justo al norte de Cumbre de Roca Negra. Las demás están en las Tierras de la Peste del Este cerca de una ciudad decrépita, en el camino a los precipicios en las Tierras del Interior y en el camino a El Portal Oscuro en Las Tierras Devastadas.$B$BVuelve cuando las hayas visto todas.",objectives={"Visita los campamentos del Festival del Solsticio de las Tierras Devastadas, las Tierras de la Peste del Este, las Tierras del Interior y la Garganta de Fuego y ve a ver al guardián de la llama."}]])
R(9324,"Robar la llama de Orgrimmar",[[description="Esta llama, robada del fuego del hogar de Orgrimmar, te inunda de calor. No conoces este poder tan primitivo, pero puede que el maestro del Conocimiento tenga más información...",objectives={"Devuelve la llama de Orgrimmar al maestro cultural del Festival."}]])
R(9325,"Robar la llama de Cima del Trueno",[[description="Esta llama, robada del fuego del chamán de Cima del Trueno, te inunda de calor. No conoces este poder tan primitivo, pero puede que el maestro del Conocimiento tenga más información...",objectives={"Devuelve la llama de Cima del Trueno al maestro cultural del Festival."}]])
R(9326,"Robar la llama de Entrañas",[[description="Esta llama, robada de las ruinas que cubren Entrañas, te inunda de calor. No conoces este poder tan primitivo, pero puede que el maestro del Conocimiento tenga más información...",objectives={"Devuelve la llama de Entrañas al maestro cultural del Festival."}]])
R(9330,"Robar la llama de Ventormenta",[[description="Esta llama, robada del fuego del hogar de Ventormenta, te inunda de calor. No conoces este poder tan primitivo, pero puede que la Liga de Cuentacuentos tenga más información...",objectives={"Devuelve la llama de Ventormenta al cuentacuentos del Festival."}]])
